const headContentRegex = /(?<=<head\s*>)[\S|\s]*(?=<\/head\s*>)/;
const headElementContent = code.match(headContentRegex);

const headElement = document.createElement("head");
headElement.innerHTML = headElementContent;
assert.strictEqual(headElement.querySelectorAll('link')?.length, 3);

const aaaaa = document.querySelectorAll('.social-icons a');
assert.lengthOf(aaaaa, 5);
aaaaa?.forEach(
  a => {
    assert.lengthOf(a?.children, 1);
    assert.equal(a?.children?.[0]?.localName, 'i');
  }
);

const iiiii = document.querySelectorAll('i');
assert.lengthOf(iiiii, 5);
iiiii?.forEach(
  i => {
    assert.isTrue(i?.classList?.contains('fab'));
  }
);

const children = document.querySelector('.text blockquote')?.children;
assert.equal(children?.[0]?.localName, 'hr');
assert.equal(children?.[1]?.localName, 'p');
assert.equal(children?.[2]?.localName, 'hr');

const lis = document.querySelectorAll('.lists li');
assert.isNotEmpty(lis);
lis.forEach(li => {
  assert.equal(li?.children?.[0]?.localName, 'h4');
  assert.equal(li?.children?.[1]?.localName, 'p');
});

const h4s = document.querySelectorAll('.lists li h4');
assert.isNotEmpty(h4s);
h4s.forEach(h4 => {
  assert.isTrue(h4?.classList?.contains('list-subtitle'));
});

const children = document.querySelector('aside')?.children;
assert.equal(children?.[0]?.localName, 'img');
assert.equal(children?.[1]?.localName, 'img');
assert.equal(children?.[2]?.localName, 'blockquote');
assert.equal(children?.[3]?.localName, 'img');

assert.equal(
  document.querySelectorAll('.image-wrapper img')?.[1]?.getAttribute('alt'),
  'image of a calculator project'
);

assert.equal(
  document.querySelectorAll('.image-wrapper img')?.[2]?.getAttribute('alt'),
  'four people working on code'
);

